package com.smartspend;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import jakarta.validation.Valid;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/auth") class AuthController{final UserRepo users;final BCryptPasswordEncoder enc;final JwtService jwt;final AuditService audit;AuthController(UserRepo u,BCryptPasswordEncoder e,JwtService j,AuditService a){users=u;enc=e;jwt=j;audit=a;}@PostMapping("/register")ResponseEntity<?> reg(@Valid @RequestBody RegisterRequest r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.status(409).body(Map.of("message","Email already registered"));User u=new User();u.name=r.name();u.email=r.email();u.password=enc.encode(r.password());users.save(u);audit.record(u,"REGISTER","User registration");return ResponseEntity.status(201).body(Map.of("message","Registration successful"));}@PostMapping("/login")Map<String,Object> login(@Valid @RequestBody AuthRequest r){User u=users.findByEmail(r.email()).orElseThrow(()->new UnauthorizedException("Invalid credentials"));if(!u.active||!enc.matches(r.password(),u.password))throw new UnauthorizedException("Invalid credentials");audit.record(u,"LOGIN_SUCCESS","Successful login");return Map.of("token",jwt.create(u),"name",u.name,"email",u.email,"role",u.role);}}
abstract class Base{User me(Authentication a,UserRepo r){return r.findByEmail(a.getName()).orElseThrow(()->new ResourceNotFoundException("User not found"));}Map<String,Object> cat(Category c){return c==null?Map.of():Map.of("id",c.id,"name",c.name,"color",c.color);}}
@RestController @RequestMapping("/api/categories") class CategoryController extends Base{final CategoryRepo cats;final AuditService audit;final UserRepo users;CategoryController(CategoryRepo c,AuditService a,UserRepo u){cats=c;audit=a;users=u;}@GetMapping List<Map<String,Object>> all(){return cats.findAll().stream().map(this::cat).toList();}@PostMapping @PreAuthorize("hasRole('ADMIN')")Map<String,Object> add(@Valid @RequestBody Category c,Authentication auth){if(c.name==null||c.name.isBlank())throw new BadRequestException("Category name is required");if(cats.findByNameIgnoreCase(c.name).isPresent())throw new ConflictException("Category already exists");Category saved=cats.save(c);audit.record(me(auth,users),"CATEGORY_CREATE","Created category "+saved.id);return cat(saved);}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")Map<String,Object> update(@PathVariable Long id,@Valid @RequestBody Category in,Authentication auth){Category c=cats.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found"));if(in.name==null||in.name.isBlank())throw new BadRequestException("Category name is required");if(cats.findByNameIgnoreCase(in.name).filter(existing->!existing.id.equals(id)).isPresent())throw new ConflictException("Category already exists");c.name=in.name;c.color=in.color;Category saved=cats.save(c);audit.record(me(auth,users),"CATEGORY_UPDATE","Updated category "+id);return cat(saved);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")void del(@PathVariable Long id,Authentication auth){if(!cats.existsById(id))throw new ResourceNotFoundException("Category not found");cats.deleteById(id);audit.record(me(auth,users),"CATEGORY_DELETE","Deleted category "+id);}}
@RestController @RequestMapping("/api/expenses") class ExpenseController extends Base{final ExpenseRepo es;final CategoryRepo cs;final UserRepo us;final AuditService audit;final NotificationService notifications;ExpenseController(ExpenseRepo e,CategoryRepo c,UserRepo u,AuditService a,NotificationService n){es=e;cs=c;us=u;audit=a;notifications=n;}Map<String,Object> out(Expense e){return Map.of("id",e.id,"amount",e.amount,"description",e.description,"date",e.date,"category",cat(e.category),"paymentMethod",e.paymentMethod,"createdAt",e.createdAt);}@GetMapping List<Map<String,Object>> all(Authentication a,@RequestParam(required=false) String paymentMethod,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) String from,@RequestParam(required=false) String to,@RequestParam(required=false) String search,@RequestParam(defaultValue="date") String sortBy,@RequestParam(defaultValue="desc") String sortDir,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){String sortField=switch(sortBy.toLowerCase(Locale.ROOT)){case "date","amount","description"->sortBy.toLowerCase(Locale.ROOT);default->throw new BadRequestException("Invalid sort field");};org.springframework.data.domain.Sort.Direction direction=switch(sortDir.toLowerCase(Locale.ROOT)){case "asc"->org.springframework.data.domain.Sort.Direction.ASC;case "desc"->org.springframework.data.domain.Sort.Direction.DESC;default->throw new BadRequestException("Invalid sort direction");};var pageable=org.springframework.data.domain.PageRequest.of(Math.max(0,page),Math.min(200,Math.max(1,size)),org.springframework.data.domain.Sort.by(direction,sortField));Long uid=me(a,us).id;org.springframework.data.jpa.domain.Specification<Expense> spec=(root,q,cb)->{var predicates=new ArrayList<jakarta.persistence.criteria.Predicate>();predicates.add(cb.equal(root.get("user").get("id"),uid));if(paymentMethod!=null&&!paymentMethod.isBlank()){try{predicates.add(cb.equal(root.get("paymentMethod"),PaymentMethod.valueOf(paymentMethod.toUpperCase(Locale.ROOT))));}catch(IllegalArgumentException ex){throw new BadRequestException("Invalid payment method");}}if(categoryId!=null)predicates.add(cb.equal(root.get("category").get("id"),categoryId));if(search!=null&&!search.isBlank())predicates.add(cb.like(cb.lower(root.get("description")),"%"+search.trim().toLowerCase(Locale.ROOT)+"%"));try{if(from!=null&&!from.isBlank())predicates.add(cb.greaterThanOrEqualTo(root.get("date"),LocalDate.parse(from)));if(to!=null&&!to.isBlank())predicates.add(cb.lessThanOrEqualTo(root.get("date"),LocalDate.parse(to)));}catch(java.time.format.DateTimeParseException ex){throw new BadRequestException("Invalid date filter");}return cb.and(predicates.toArray(new jakarta.persistence.criteria.Predicate[0]));};return es.findAll(spec,pageable).map(this::out).getContent();}@GetMapping("/{id}")Map<String,Object> one(@PathVariable Long id,Authentication a){return out(es.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Expense not found")));}@PostMapping ResponseEntity<?> add(@Valid @RequestBody ExpenseRequest r,Authentication a){Expense e=new Expense(r.amount(),r.description(),r.date(),cs.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found")),r.paymentMethod(),me(a,us));Expense saved=es.save(e);audit.record(e.user,"EXPENSE_CREATE","Created expense "+e.id);notifications.notify(e.user,"EXPENSE_CREATED","Expense recorded: "+e.description);notifications.evaluate(e.user);return ResponseEntity.status(201).body(out(saved));}@PutMapping("/{id}")Map<String,Object> update(@PathVariable Long id,@Valid @RequestBody ExpenseRequest r,Authentication a){Expense e=es.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Expense not found"));e.amount=r.amount();e.description=r.description();e.date=r.date();e.paymentMethod=r.paymentMethod();e.category=cs.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found"));audit.record(e.user,"EXPENSE_UPDATE","Updated expense "+e.id);Expense saved=es.save(e);notifications.evaluate(e.user);return out(saved);}@DeleteMapping("/{id}")void del(@PathVariable Long id,Authentication a){Expense e=es.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Expense not found"));es.delete(e);audit.record(e.user,"EXPENSE_DELETE","Deleted expense "+id);notifications.evaluate(e.user);}}
@RestController @RequestMapping("/api/incomes") class IncomeController extends Base{final IncomeRepo is;final UserRepo us;final AuditService audit;final NotificationService notifications;IncomeController(IncomeRepo i,UserRepo u,AuditService a,NotificationService n){is=i;us=u;audit=a;notifications=n;}Map<String,Object> out(Income x){return Map.of("id",x.id,"amount",x.amount,"source",x.source,"description",x.description==null?"":x.description,"date",x.date);}@GetMapping List<Map<String,Object>> all(Authentication a,@RequestParam(required=false) String from,@RequestParam(required=false) String to,@RequestParam(required=false) String search,@RequestParam(defaultValue="date") String sortBy,@RequestParam(defaultValue="desc") String sortDir,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){String sortField=switch(sortBy.toLowerCase(Locale.ROOT)){case "date","amount","source"->sortBy.toLowerCase(Locale.ROOT);default->throw new BadRequestException("Invalid sort field");};org.springframework.data.domain.Sort.Direction direction=switch(sortDir.toLowerCase(Locale.ROOT)){case "asc"->org.springframework.data.domain.Sort.Direction.ASC;case "desc"->org.springframework.data.domain.Sort.Direction.DESC;default->throw new BadRequestException("Invalid sort direction");};var pageable=org.springframework.data.domain.PageRequest.of(Math.max(0,page),Math.min(200,Math.max(1,size)),org.springframework.data.domain.Sort.by(direction,sortField));Long uid=me(a,us).id;org.springframework.data.jpa.domain.Specification<Income> spec=(root,q,cb)->{var predicates=new ArrayList<jakarta.persistence.criteria.Predicate>();predicates.add(cb.equal(root.get("user").get("id"),uid));if(search!=null&&!search.isBlank()){String term="%"+search.trim().toLowerCase(Locale.ROOT)+"%";predicates.add(cb.or(cb.like(cb.lower(root.get("source")),term),cb.like(cb.lower(root.get("description")),term)));}try{if(from!=null&&!from.isBlank())predicates.add(cb.greaterThanOrEqualTo(root.get("date"),LocalDate.parse(from)));if(to!=null&&!to.isBlank())predicates.add(cb.lessThanOrEqualTo(root.get("date"),LocalDate.parse(to)));}catch(java.time.format.DateTimeParseException ex){throw new BadRequestException("Invalid date filter");}return cb.and(predicates.toArray(new jakarta.persistence.criteria.Predicate[0]));};return is.findAll(spec,pageable).map(this::out).getContent();}@GetMapping("/{id}")Map<String,Object> one(@PathVariable Long id,Authentication a){return out(is.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Income not found")));}@PostMapping ResponseEntity<?> add(@Valid @RequestBody IncomeRequest r,Authentication a){Income x=new Income(r.amount(),r.source(),r.description(),r.date(),me(a,us));Income saved=is.save(x);audit.record(x.user,"INCOME_CREATE","Created income "+x.id);notifications.evaluate(x.user);return ResponseEntity.status(201).body(out(saved));}@PutMapping("/{id}")Map<String,Object> update(@PathVariable Long id,@Valid @RequestBody IncomeRequest r,Authentication a){Income x=is.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Income not found"));x.amount=r.amount();x.source=r.source();x.description=r.description();x.date=r.date();audit.record(x.user,"INCOME_UPDATE","Updated income "+x.id);Income saved=is.save(x);notifications.evaluate(x.user);return out(saved);}@DeleteMapping("/{id}")void del(@PathVariable Long id,Authentication a){Income x=is.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Income not found"));is.delete(x);audit.record(x.user,"INCOME_DELETE","Deleted income "+id);notifications.evaluate(x.user);}}
@RestController @RequestMapping("/api/budgets") class BudgetController extends Base{final BudgetRepo bs;final CategoryRepo cs;final UserRepo us;final ExpenseRepo es;final AuditService audit;final NotificationService notifications;BudgetController(BudgetRepo b,CategoryRepo c,UserRepo u,ExpenseRepo e,AuditService a,NotificationService n){bs=b;cs=c;us=u;es=e;audit=a;notifications=n;}Map<String,Object> out(Budget b){var from=LocalDate.of(b.year,b.month,1);var used=es.findByUserIdAndDateBetween(b.user.id,from,from.plusMonths(1).minusDays(1)).stream().filter(x->b.category==null||x.category.id.equals(b.category.id)).map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);double pct=b.amount.signum()==0?0:used.multiply(BigDecimal.valueOf(100)).divide(b.amount,2,RoundingMode.HALF_UP).doubleValue();return Map.of("id",b.id,"amount",b.amount,"month",b.month,"year",b.year,"category",b.category==null?"Overall":b.category.name,"used",used,"remaining",b.amount.subtract(used),"percentage",pct,"status",FinancialRules.budgetStatus(used,b.amount));}@GetMapping List<Map<String,Object>> all(Authentication a){return bs.findByUserId(me(a,us).id).stream().map(this::out).toList();}@GetMapping("/{id}")Map<String,Object> one(@PathVariable Long id,Authentication a){return out(bs.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Budget not found")));}@PostMapping ResponseEntity<?> add(@Valid @RequestBody BudgetRequest r,Authentication a){Budget b=new Budget();b.amount=r.amount();b.month=r.month();b.year=r.year();b.user=me(a,us);b.category=r.categoryId()==null?null:cs.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found"));Budget saved=bs.save(b);audit.record(b.user,"BUDGET_CREATE","Created budget "+b.id);notifications.notify(b.user,"BUDGET_CREATED","Budget created for "+b.month+"/"+b.year);notifications.evaluate(b.user);return ResponseEntity.status(201).body(out(saved));}@PutMapping("/{id}")Map<String,Object> update(@PathVariable Long id,@Valid @RequestBody BudgetRequest r,Authentication a){Budget b=bs.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Budget not found"));b.amount=r.amount();b.month=r.month();b.year=r.year();b.category=r.categoryId()==null?null:cs.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found"));audit.record(b.user,"BUDGET_UPDATE","Updated budget "+b.id);Budget saved=bs.save(b);notifications.evaluate(b.user);return out(saved);}@DeleteMapping("/{id}")void del(@PathVariable Long id,Authentication a){Budget b=bs.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Budget not found"));bs.delete(b);audit.record(b.user,"BUDGET_DELETE","Deleted budget "+id);notifications.evaluate(b.user);}}
